CREATE TABLE users (id BIGINT NOT NULL AUTO_INCREMENT, email VARCHAR(190) NOT NULL UNIQUE, password_hash VARCHAR(255) NOT NULL, full_name VARCHAR(120) NOT NULL, PRIMARY KEY(id));
CREATE TABLE student_profiles (user_id BIGINT NOT NULL, state VARCHAR(100), category VARCHAR(50), gender VARCHAR(30), education_level VARCHAR(50), course VARCHAR(160), academic_year VARCHAR(20), marks DOUBLE, family_income BIGINT, PRIMARY KEY(user_id), CONSTRAINT fk_profile_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE);
CREATE TABLE scholarships (id BIGINT NOT NULL AUTO_INCREMENT, name VARCHAR(255) NOT NULL, provider VARCHAR(255) NOT NULL, source_url VARCHAR(500) NOT NULL, description VARCHAR(1000) NOT NULL, verification_status VARCHAR(100) NOT NULL, state VARCHAR(100), category VARCHAR(100), gender VARCHAR(30), education_level VARCHAR(100), course VARCHAR(160), academic_year VARCHAR(20), min_marks DOUBLE, max_income BIGINT, benefit VARCHAR(255), opening_date VARCHAR(40), closing_date VARCHAR(40), last_verified VARCHAR(40), demonstration BOOLEAN NOT NULL DEFAULT TRUE, PRIMARY KEY(id));
CREATE TABLE saved_scholarships (id BIGINT NOT NULL AUTO_INCREMENT, user_id BIGINT NOT NULL, scholarship_id BIGINT NOT NULL, PRIMARY KEY(id), UNIQUE KEY uq_saved_user_scholarship(user_id,scholarship_id), CONSTRAINT fk_saved_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_saved_scholarship FOREIGN KEY(scholarship_id) REFERENCES scholarships(id) ON DELETE CASCADE);
CREATE TABLE scholarship_applications (id BIGINT NOT NULL AUTO_INCREMENT, user_id BIGINT NOT NULL, scholarship_id BIGINT NOT NULL, status VARCHAR(40) NOT NULL, updated_at TIMESTAMP NOT NULL, PRIMARY KEY(id), UNIQUE KEY uq_app_user_scholarship(user_id,scholarship_id), CONSTRAINT fk_app_user FOREIGN KEY(user_id) REFERENCES users(id) ON DELETE CASCADE, CONSTRAINT fk_app_scholarship FOREIGN KEY(scholarship_id) REFERENCES scholarships(id) ON DELETE CASCADE);
